insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-fr-a1-6c59390cc2b7', 'fr', 'A1', 'Ma famille et le parc', 'Bonjour ! Je m''appelle Marie. Voici ma famille. Mon père s''appelle Jean. Ma mère s''appelle Sophie. J''ai un frère et une sœur. Mon frère a un vélo et ma sœur a une poupée. Nous avons aussi un chat noir et une souris blanche. Le chat adore la souris, mais la souris a peur du chat !

Aujourd''hui, nous allons au parc. Dans le parc, il y a des arbres et des fleurs. Les arbres sont grands. Les fleurs sont belles. Je vois un oiseau et une fleur rouge. L''oiseau chante. J''aime le parc !

