insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-fr-a1-d2c376639c70', 'fr', 'A1', 'Ma famille', 'Je m’appelle Lucas. J’ai une petite famille. Mon père s’appelle Paulo et ma mère s’appelle Ana. J’ai un frère et une sœur. Mon frère est grand et ma sœur est petite. Nous avons un chien et un chat. Le chien s’appelle Rex et le chat s’appelle Mina.

Dans notre maison, il y a des chambres, une cuisine, un salon et une salle de bain. Les chambres sont bleues. La cuisine est blanche. Le salon est jaune. La salle de bain est verte. Nous aimons les repas ensemble. Le soir, nous regardons des films. Les films sont amusants. J’aime ma famille.', '[{"answer_index":0,"explanation_pt_br":"A palavra ''frère'' é masculina e singular, portanto usamos o artigo indefinido ''un''.","options":["un","une","des","le"],"prompt":"Complétez la phrase : « J’ai ___ frère. »"},{"answer_index":1,"explanation_pt_br":"A palavra ''sœur'' é feminina e singular, portanto usamos o artigo definido ''la''.","options":["Le","La","Les","Un"],"prompt":"Complétez la phrase : « ___ sœur s’appelle Ana. »"},{"answer_index":1,"explanation_pt_br":"''Chambres'' é feminino e plural, então o adjetivo concorda em gênero e número: ''bleues''.","options":["Les chambres sont bleus.","Les chambres sont bleues.","La chambre sont bleue.","Le chambres sont bleues."],"prompt":"Quelle phrase est correcte ?"}]'::jsonb, 0, true)
