insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-fr-a1-0299d20c015a', 'fr', 'A1', 'Au marché', 'Marie habite à Paris. Samedi, elle va au marché avec son ami Paul. Ils achètent des fruits et des légumes. Marie adore les bananes. Elle voit des bananes jaunes et des pommes vertes. Elle achète une pomme et un pain. Le pain est frais.

Paul achète des tomates et des carottes. Les tomates sont rouges, mais les carottes sont orange. Le vendeur est très sympa. Il donne un sac à Marie. Le sac est grand et solide. Marie met les fruits et les légumes dans le sac. Elle est heureuse. Paul et Marie rentrent à la maison.

Ils préparent une salade avec les tomates et les carottes. Marie mange la pomme. C''est bon!', '[{"answer_index":1,"explanation_pt_br":"Pomme é feminino singular; usamos une (indefinido). Un é masculino, des é plural, le é definido singular masculino.","options":["un","une","des","le"],"prompt":"Complétez avec le bon article : Marie achète ___ pomme."},{"answer_index":2,"explanation_pt_br":"Pain é masculino singular (le pain). Os outros estão no feminino ou no plural.","options":["bananes","carottes","pain","pommes"],"prompt":"Dans le texte, quel mot est au masculin singulier ?"},{"answer_index":2,"explanation_pt_br":"Fruits é o plural de fruit (masculino). O artigo indefinido plural é des para ambos os gêneros.","options":["Parce que fruits est masculin singulier","Parce que fruits est féminin pluriel","Parce que fruits est masculin pluriel","Parce que fruits est féminin singulier"],"prompt":"Pourquoi l''article « des » est-il utilisé dans « des fruits » ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-fr-a1-c82cc7f8f6b7', 'fr', 'A1', 'Les élections des délégués', 'Marie et Paul sont dans la même classe. Aujourd''hui, il y a les élections des délégués. Marie est une candidate. Paul est un candidat. Les élèves vont voter pour un garçon ou pour une fille.

Le directeur ouvre la salle. Des affiches sont sur les murs. Les bulletins sont sur une grande table. Le professeur explique le vote : chaque élève prend un bulletin et écrit un nom.

Marie parle : « Je veux une école propre et des activités pour tous. » Paul dit : « Je propose des sports et une bibliothèque. » Après le vote, le professeur compte les voix. Marie gagne ! Elle est contente. Les élèves applaudissent.', '[{"answer_index":1,"explanation_pt_br":"« candidate » é um substantivo feminino singular, por isso usamos o artigo indefinido feminino « une ».","options":["un","une","des","le"],"prompt":"Complète avec l''article correct : « Marie est ___ candidate. »"},{"answer_index":2,"explanation_pt_br":"« élèves » é plural (masculino ou misto). O artigo definido plural é « les ».","options":["La","Le","Les","Un"],"prompt":"Complète avec l''article correct : « ___ élèves vont voter. »"},{"answer_index":3,"explanation_pt_br":"No texto, Paul não especifica quais esportes, então usamos o artigo indefinido plural « des ».","options":["un","une","les","des"],"prompt":"Complète : « Paul propose ___ sports. »"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();
